import "fmt"

func main() {
	vals := []int{}
	mins := []int{}
	push := func(v int) {
		vals = append(vals, v)
		if len(mins) == 0 || v < mins[len(mins)-1] {
			mins = append(mins, v)
		} else {
			mins = append(mins, mins[len(mins)-1])
		}
	}
	push(5)
	push(1)
	vals = vals[:len(vals)-1]
	push(4)
	fmt.Println(mins[len(mins)-1])
}

