	nums := []int{1, 4, 2, 10, 3}
	window := nums[0] + nums[1] + nums[2]
	best := window
	for i := 3; i < len(nums); i++ {
		window = window - nums[i-3] + nums[i]
		if window > best {
			best = window
		}
	}
	fmt.Println(best)
}

