import "fmt"

func main() {
	nums := []int{2, 1, 5, 1, 3, 2}
	best := 0
	left := 0
	sum := 0
	for right := 0; right < len(nums); right++ {
		sum += nums[right]
		for sum > 7 {
			sum -= nums[left]
			left++
		}
		if right-left+1 > best {
			best = right - left
		}
	}
	fmt.Println(best)
}

