import "fmt"

func main() {
	s := "abba"
	seen := map[byte]int{}
	left := 0
	best := 0
	for right := 0; right < len(s); right++ {
		c := s[right]
		if _, ok := seen[c]; ok {
			left = seen[c]
		}
		seen[c] = right
		if right-left+1 > best {
			best = right - left + 1
		}
	}
	fmt.Println(best)
}
